1	//! Tests for the flashback mechanic and all 15 flashback cards.
2	//!
3	//! Flashback allows casting a spell from the graveyard for an alternative cost.
4	//! After resolution (or countering), the spell is exiled instead of returning to graveyard.
5	
6	mod common;
7	
8	use common::*;
9	use mtg_engine::actions::{Action, Target};
10	use mtg_engine::cards::CardRegistry;
11	use mtg_engine::engine;
12	use mtg_engine::types::*;
13	
14	fn registry() -> CardRegistry {
15	    CardRegistry::with_all_cards()
16	}
17	
18	// ── System tests: flashback mechanics ──────────────────────────────
19	
20	/// Flashback is offered when a card with flashback_cost is in the graveyard
21	/// and the player has enough mana.
22	#[test]
23	fn flashback_offered_from_graveyard() {
24	    let reg = registry();
25	    let mut state = game_at_step(Step::PrecombatMain, P0);
26	
27	    let card_id = reg.get_id_by_name("Geistflame").unwrap();
28	    let card = state.create_object(card_id, P0, Zone::Graveyard, None, None);
29	    state.get_object_mut(card).unwrap().name = "Geistflame".into();
30	
31	    // Geistflame flashback cost is {3}{R}.
32	    state.get_player_mut(P0).mana_pool.add(ManaType::Red, 4);
33	
34	    let legal = engine::legal_actions(&state, &reg);
35	    let has_flashback_cast = legal.actions.iter().any(|a| {
36	        matches!(a, Action::CastSpell { object_id, .. } if *object_id == card)
37	    });
38	    assert!(has_flashback_cast,
39	        "legal_actions should offer CastSpell for a flashback card in the graveyard");
40	}
41	
42	/// A card with flashback in the hand should only be castable at its normal cost,
43	/// not via flashback.
44	#[test]
45	fn flashback_not_offered_from_hand() {
46	    let reg = registry();
47	    let mut state = game_at_step(Step::PrecombatMain, P0);
48	
49	    let card = spell_in_hand(&mut state, &reg, "Geistflame", P0);
50	
51	    // Give exactly {R} (enough for normal Geistflame, not enough for {3}{R} flashback).
52	    state.get_player_mut(P0).mana_pool.add(ManaType::Red, 1);
53	
54	    let legal = engine::legal_actions(&state, &reg);
55	    let has_cast = legal.actions.iter().any(|a| {
56	        matches!(a, Action::CastSpell { object_id, .. } if *object_id == card)
57	    });
58	    // It IS offered — as a normal cast from hand at cost {R}.
59	    assert!(has_cast,
60	        "Geistflame should be castable from hand at normal cost R");
61	}
62	
63	/// Flashback is NOT offered when the player lacks mana for the flashback cost.
64	#[test]
65	fn flashback_not_offered_without_mana() {
66	    let reg = registry();
67	    let mut state = game_at_step(Step::PrecombatMain, P0);
68	
69	    let card_id = reg.get_id_by_name("Geistflame").unwrap();
70	    let card = state.create_object(card_id, P0, Zone::Graveyard, None, None);
71	    state.get_object_mut(card).unwrap().name = "Geistflame".into();
72	
73	    // Only {R} — not enough for flashback cost {3}{R}.
74	    state.get_player_mut(P0).mana_pool.add(ManaType::Red, 1);
75	
76	    let legal = engine::legal_actions(&state, &reg);
77	    let has_flashback_cast = legal.actions.iter().any(|a| {
78	        matches!(a, Action::CastSpell { object_id, .. } if *object_id == card)
79	    });
80	    assert!(!has_flashback_cast,
81	        "Flashback should not be offered with insufficient mana");
82	}
83	
84	/// A spell cast via flashback is exiled (not sent to graveyard) after resolution.
85	#[test]
86	fn flashback_spell_is_exiled_after_resolve() {
87	    let reg = registry();
88	    let mut state = game_at_step(Step::PrecombatMain, P0);
89	
90	    let card_id = reg.get_id_by_name("Geistflame").unwrap();
91	    let card = state.create_object(card_id, P0, Zone::Graveyard, None, None);
92	    state.get_object_mut(card).unwrap().name = "Geistflame".into();
93	
94	    // Flashback cost: {3}{R}.
95	    state.get_player_mut(P0).mana_pool.add(ManaType::Red, 4);
96	
97	    state = cast_and_resolve(
98	        &state,
99	        &reg,
100	        card,
101	        vec![Target::Player(P1)],
102	    );
103	
104	    assert_eq!(state.get_object(card).unwrap().zone, Zone::Exile,
105	        "Flashback spell should be exiled after resolution, not in graveyard");
106	}
107	
108	/// A spell cast normally from hand goes to graveyard after resolution.
109	#[test]
110	fn normal_cast_goes_to_graveyard() {
111	    let reg = registry();
112	    let mut state = game_at_step(Step::PrecombatMain, P0);
113	
114	    let card = castable_spell(&mut state, &reg, "Geistflame", P0);
115	
116	    state = cast_and_resolve(
117	        &state,
118	        &reg,
119	        card,
120	        vec![Target::Player(P1)],
121	    );
122	
123	    assert_eq!(state.get_object(card).unwrap().zone, Zone::Graveyard,
124	        "Normal cast should go to graveyard after resolution");
125	}
126	
127	/// A flashback spell that is countered should still be exiled (not graveyard).
128	#[test]
129	fn flashback_spell_countered_is_exiled() {
130	    let reg = registry();
131	    let mut state = game_at_step(Step::PrecombatMain, P0);
132	
133	    // P0 casts Geistflame from graveyard via flashback.
134	    let gf_id = reg.get_id_by_name("Geistflame").unwrap();
135	    let gf = state.create_object(gf_id, P0, Zone::Graveyard, None, None);
136	    state.get_object_mut(gf).unwrap().name = "Geistflame".into();
137	    state.get_player_mut(P0).mana_pool.add(ManaType::Red, 4);
138	
139	    state = engine::submit_action(
140	        &state,
141	        &Action::CastSpell { object_id: gf, targets: vec![Target::Player(P1)], sacrifice: None, exile_count: None, alternative_cost: None },
142	        &reg,
143	    );
144	
145	    // P1 casts Counterspell targeting Geistflame on the stack.
146	    let cs = spell_in_hand(&mut state, &reg, "Counterspell", P1);
147	    add_mana_for(&mut state, &reg, "Counterspell", P1);
148	    state.priority_player = Some(P1);
149	
150	    state = engine::submit_action(
151	        &state,
152	        &Action::CastSpell { object_id: cs, targets: vec![Target::Object(gf)], sacrifice: None, exile_count: None, alternative_cost: None },
153	        &reg,
154	    );
155	    // Resolve the Counterspell (top of stack).
156	    mtg_engine::stack::resolve_top_of_stack(&mut state, &reg);
157	
158	    assert_eq!(state.get_object(gf).unwrap().zone, Zone::Exile,
159	        "A flashback spell that is countered should be exiled");
160	    assert_eq!(state.get_object(cs).unwrap().zone, Zone::Graveyard,
161	        "Counterspell itself goes to graveyard normally");
162	}
163	
164	/// mill_cards moves cards from library to graveyard.
165	#[test]
166	fn mill_cards_moves_to_graveyard() {
167	    let reg = registry();
168	    let mut state = game_at_step(Step::PrecombatMain, P0);
169	
170	    // Manually stock P1's library with 5 cards.
171	    let mountain_id = reg.get_id_by_name("Mountain").unwrap();
172	    let mut lib_cards = Vec::new();
173	    for _ in 0..5 {
174	        let obj = state.create_object(mountain_id, P1, Zone::Library, None, None);
175	        state.get_object_mut(obj).unwrap().name = "Mountain".into();
176	        lib_cards.push(obj);
177	    }
178	    state.get_player_mut(P1).library_order = lib_cards.clone();
179	
180	    // Mill 3 cards.
181	    engine::mill_cards(&mut state, P1, 3);
182	
183	    // First 3 should be in graveyard, last 2 remain in library.
184	    for &id in &lib_cards[0..3] {
185	        assert_eq!(state.get_object(id).unwrap().zone, Zone::Graveyard,
186	            "Milled card should be in graveyard");
187	    }
188	    for &id in &lib_cards[3..5] {
189	        assert_eq!(state.get_object(id).unwrap().zone, Zone::Library,
